contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We act as the owner because this contract deployed C.
    // Single public function with inputs: amount to withdraw.
    function run(uint amount) public payable {
        require(true);
        // record balance before
        uint balBefore = address(c).balance;

        bool reverted;
        // call withdraw and capture whether it reverts
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;

        // General rule: if the call reverted, balance unchanged; otherwise balance decreased by exactly amount or to zero if amount > balBefore
        // However withdraw uses transfer which will revert if amount > balBefore, so successful case must have balAfter == balBefore - amount
        // and cannot decrease by more than amount. Expressed generally:
        assert(reverted ? (balAfter == balBefore) : (balBefore >= amount && balAfter + amount == balBefore));
    }

    // receive to accept Ether from C when withdraw uses transfer
    receive() external payable { }
}

